function report = verifyBrightnessConstrainedBnpCounting(varargin)
%VERIFYBRIGHTNESSCONSTRAINEDBNPCOUNTING Sweep concentration for BNP counting.
%
%   report = verifyBrightnessConstrainedBnpCounting()
%   report = verifyBrightnessConstrainedBnpCounting( ...
%       'moleculeCounts',[10 20 40 56], 'nFrames',500)
%
%   This is a simulation-based calibration harness, not a unit test. It
%   reports count bias and decision probabilities without asserting that the
%   experimental dense-trajectory sampler passes every concentration.

    parser = inputParser;
    addParameter(parser, 'moleculeCounts', [10 20 40]);
    addParameter(parser, 'nFrames', 300);
    addParameter(parser, 'burnInSweeps', 100);
    addParameter(parser, 'posteriorSweeps', 150);
    addParameter(parser, 'rngSeed', 41);
    parse(parser, varargin{:});
    settings = parser.Results;

    moleculeCounts = round(settings.moleculeCounts(:));
    nCondition = numel(moleculeCounts);
    trueMeanInFocus = nan(nCondition, 1);
    posteriorMeanInFocus = nan(nCondition, 1);
    meanCountBias = nan(nCondition, 1);
    frameMapAccuracy = nan(nCondition, 1);
    medianDecisionProbability = nan(nCondition, 1);
    trueContributingIdentities = nan(nCondition, 1);
    posteriorMapActiveIdentities = nan(nCondition, 1);
    activeCountDecisionProbability = nan(nCondition, 1);
    countDiagnosticsPassed = false(nCondition, 1);
    poolSaturationFraction = nan(nCondition, 1);

    for condition = 1:nCondition
        nMolecule = moleculeCounts(condition);
        out = simulateMembraneDiffusionParticleTracking( ...
            'nMolecules', nMolecule, ...
            'nFrames', settings.nFrames, ...
            'rngSeed', settings.rngSeed + condition - 1, ...
            'runExperimentalBnpSampler', true, ...
            'bnpBrightnessMode', 'fixed', ...
            'bnpCalibratedBrightnessScale', 1, ...
            'bnpPoolSize', min(64, nMolecule + 8), ...
            'bnpBurnInSweeps', settings.burnInSweeps, ...
            'bnpPosteriorSweeps', settings.posteriorSweeps, ...
            'blinkOffRateS', 0, ...
            'blinkOnRateS', 0, ...
            'bleachProbabilityPerAbsorbedPhoton', 0, ...
            'makeFigure', false, ...
            'writeOutputs', false, ...
            'saveFigures', false, ...
            'verbose', false);

        bnp = out.experimentalBnp;
        expectedSignal = out.photophysics.detectedRateS * ...
            out.options.dtS;
        trueFrameCount = sum(expectedSignal >= ...
            out.options.bnpInFocusPhotonThreshold, 1).';
        trueMeanInFocus(condition) = mean(trueFrameCount);
        posteriorMeanInFocus(condition) = ...
            bnp.posteriorMeanEmittersInFocus;
        meanCountBias(condition) = posteriorMeanInFocus(condition) - ...
            trueMeanInFocus(condition);
        frameMapAccuracy(condition) = mean( ...
            bnp.frameEmitterCountPosterior.mapCount == trueFrameCount);
        medianDecisionProbability(condition) = ...
            bnp.medianFrameCountDecisionProbability;
        trueContributingIdentities(condition) = ...
            bnp.trueContributingMolecules;
        posteriorMapActiveIdentities(condition) = ...
            bnp.posteriorMapActiveEmitterCount;
        activeCountDecisionProbability(condition) = ...
            bnp.activeEmitterCountDecisionProbability;
        countDiagnosticsPassed(condition) = ...
            bnp.countDiagnosticsPassed;
        poolSaturationFraction(condition) = ...
            bnp.fractionPoolSaturated;
    end

    report = table(moleculeCounts, trueMeanInFocus, ...
        posteriorMeanInFocus, meanCountBias, frameMapAccuracy, ...
        medianDecisionProbability, trueContributingIdentities, ...
        posteriorMapActiveIdentities, activeCountDecisionProbability, ...
        countDiagnosticsPassed, poolSaturationFraction);
    disp(report);
end
